import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`concentration`,heroTitle:`Map customer concentration in minutes`,heroSubtitle:`Perplexity Computer researches public disclosures, job postings, and news to surface concentration risks — automatically.`,inputUrlCta:`Analyze my target`,inputUrlPlaceholder:`e.g. www.company.com`,inputUrlPrefill:`Go to {url} and run a full customer and supplier concentration analysis for private equity due diligence. (1) Extract the company's disclosed customers and suppliers from SEC filings, investor presentations, earnings transcripts, and press releases. (2) Cross-reference Glassdoor reviews, job postings, and news mentions to identify undisclosed relationships. (3) Estimate revenue concentration by customer — flag any customer above 10% of revenue. (4) Identify key supplier dependencies and single-source risks. (5) Assess churn risk based on contract lengths, switching costs, and competitive alternatives. (6) Deliver a structured concentration risk report with a summary table, risk scores, and sourced citations.`,heroOverlaySteps:[`Scanning SEC filings, press releases, and earnings transcripts`,`Cross-referencing Glassdoor, job postings, and news for undisclosed relationships`,`Estimating revenue splits and supplier dependencies`,`Concentration risk report, summary table, and risk scores — ready to share`],generatingSteps:[`Visiting {url} to extract disclosed customer and supplier relationships`,`Designing an agent to cross-reference filings, reviews, and news for hidden dependencies`,`Configuring revenue concentration estimates and single-source risk flags`,`Setting up the final risk report with summary tables and sourced citations`],featureSectionTitle:`From filings to risk flags`,featureCardTitles:[`Connects to your diligence stack`,`Deliverables ready to present`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`SEC EDGAR, PitchBook, LinkedIn, Glassdoor — Computer plugs into your tools so concentration analysis pulls from every available source.`,`Concentration tables. Risk scores. Supplier dependency maps. Computer delivers a structured diligence memo you can drop into your IC deck.`],capabilitySectionTitle:`Your diligence analyst, on autopilot`,capabilitySectionSubtitle:`Paste a company URL, step away, come back to a complete concentration risk report.`,capabilityCards:[{title:`Customer Extraction`,description:`Computer can parse 10-K filings, earnings calls, and press releases to identify every named customer and estimate revenue share.`},{title:`Supplier Mapping`,description:`Computer can trace supplier relationships through procurement data, job postings, and industry databases to flag single-source risks.`},{title:`Churn Risk Scoring`,description:`Computer can assess customer stickiness by analyzing contract terms, switching costs, and competitive alternatives — then assign risk scores.`},{title:`Connect Your Tools`,description:`Computer connects to SEC EDGAR, PitchBook, LinkedIn, and your internal data room — so every analysis is comprehensive.`},{title:`Remember & Learn`,description:`Computer can remember your investment criteria and prior diligence findings across sessions — so every analysis builds on what came before.`},{title:`Filing Alerts`,description:`Computer can monitor new SEC filings and press releases for portfolio companies — and alert you when concentration risk shifts.`}]});export{t as default};
